import{_ as r,o as i,c as o,a0 as n}from"./chunks/framework.BYCjvD8D.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Research Games","text":"Evolution learns to play.","tagline":"A public, interactive research laboratory for neuroevolution, reinforcement learning and browser computing.","actions":[{"theme":"brand","text":"Train in your browser","link":"/demo/"},{"theme":"alt","text":"Read the algorithm","link":"/algorithm"}]}},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),t={name:"index.md"};function a(s,e,l,p,m,d){return i(),o("div",null,[...e[0]||(e[0]=[n('<h2 id="first-experiment-—-mari-o-inspired-neuroevolution" tabindex="-1">First experiment — MarI/O-inspired neuroevolution <a class="header-anchor" href="#first-experiment-—-mari-o-inspired-neuroevolution" aria-label="Permalink to &quot;First experiment — MarI/O-inspired neuroevolution&quot;">​</a></h2><p>The <a href="https://www.youtube.com/watch?v=qv6UVOQ0F44" target="_blank" rel="noreferrer">2015 MarI/O demonstration</a> by SethBling shows evolving neural networks learning to play <strong>Super Mario World</strong>, using Lua inside the BizHawk emulator.</p><p>Our experiment is a <strong>new TypeScript implementation</strong> based on published NeuroEvolution of Augmenting Topologies principles, with an <strong>original</strong> game, terrain, character and physical rules. It is not a literal Lua translation, nor is it a Super Mario emulator.</p><ul><li>Evolving weights and network connections with genome innovation markers, speciation, crossover and fitness sharing.</li><li>Deterministic episodes for reproducible comparisons.</li><li>Game rendering in the browser, with a live 13×13 local sensor grid.</li><li>Training in a Web Worker; WebGPU for Three.js neural-topology rendering when supported, with a WebGL 2 fallback.</li><li>Export of the best genome as JSON.</li></ul><p><strong>No server, Python runtime, original game ROM, Nintendo art, or hosted training service is required.</strong></p><p><a href="./original-mar-io">Explore the source review</a> · <a href="./methodology">Inspect methods</a> · <a href="./roadmap">Read the milestones</a></p>',6)])])}const c=r(t,[["render",a]]);export{h as __pageData,c as default};
